import{_ as s,o as n,c as e,a2 as t}from"./chunks/framework.XXezeKOl.js";const g=JSON.parse('{"title":"如何使用本站学习","description":"本站的内容结构、三条学习路径、代码语言切换方式，以及高效学习的建议。","frontmatter":{"title":"如何使用本站学习","description":"本站的内容结构、三条学习路径、代码语言切换方式，以及高效学习的建议。"},"headers":[],"relativePath":"guide/00-intro/how-to-learn.md","filePath":"guide/00-intro/how-to-learn.md","lastUpdated":null}'),i={name:"guide/00-intro/how-to-learn.md"};function l(r,a,p,o,d,h){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="如何使用本站学习" tabindex="-1">如何使用本站学习 <a class="header-anchor" href="#如何使用本站学习" aria-label="Permalink to &quot;如何使用本站学习&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>了解本站的整体结构：16 个模块、4 个篇章，以及实战项目、论文、面试等板块</li><li>根据自己的背景选择合适的学习路径</li><li>学会使用代码语言切换，并准备好运行示例代码</li><li>掌握一套「读 → 跑 → 改 → 测」的学习方法</li></ul></div><h2 id="站点结构" tabindex="-1">站点结构 <a class="header-anchor" href="#站点结构" aria-label="Permalink to &quot;站点结构&quot;">​</a></h2><p>本站内容分为两大部分：<strong>知识库</strong>（按模块系统学习）和<strong>配套板块</strong>（项目、路线、论文、面试）。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MaxAI Agent Lab</span></span>
<span class="line"><span>├── 知识库 /guide/              16 个模块，4 个篇章</span></span>
<span class="line"><span>│   ├── 基础篇  00 导读 · 01 编程基础 · 02 大模型原理 · 03 大模型 API</span></span>
<span class="line"><span>│   ├── 核心篇  04 提示词 · 05 Tool Calling · 06 Agent 循环</span></span>
<span class="line"><span>│   │          07 上下文工程 · 08 记忆系统 · 09 RAG 知识库</span></span>
<span class="line"><span>│   ├── 生态篇  10 MCP 与 A2A · 11 框架实战 · 12 多 Agent · 13 Coding 与 Computer-Use</span></span>
<span class="line"><span>│   └── 工程篇  14 评估与可观测性 · 15 安全与生产化</span></span>
<span class="line"><span>├── 学习路线 /roadmap/          三条路径 + 12 周计划</span></span>
<span class="line"><span>├── 实战项目 /projects/         10 个由浅入深的项目</span></span>
<span class="line"><span>├── 论文精读 /papers/           Agent 领域的关键论文</span></span>
<span class="line"><span>├── 面试题  /interview/        基础、RAG、工程与系统设计</span></span>
<span class="line"><span>└── 术语表  /glossary           常见术语中英对照与解释</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>四个篇章的定位：</p><table tabindex="0"><thead><tr><th>篇章</th><th>模块</th><th>解决的问题</th></tr></thead><tbody><tr><td>基础篇</td><td>00–03</td><td>Agent 是什么；需要哪些编程基础；大模型怎么工作；API 怎么调用</td></tr><tr><td>核心篇</td><td>04–09</td><td>构建一个 Agent 的核心能力：提示词、工具、循环、上下文、记忆、知识库</td></tr><tr><td>生态篇</td><td>10–13</td><td>协议（MCP、A2A）、主流框架、多 Agent 协作、编程与电脑操作类 Agent</td></tr><tr><td>工程篇</td><td>14–15</td><td>让 Agent 可评估、可观测、安全、可上线</td></tr></tbody></table><p>核心篇是全站的重心。特别建议先<strong>不用框架手写一遍 Agent</strong>（<a href="/guide/06-agent-loop/handwritten-agent">06 Agent 循环</a>），再去学框架。理解了底层循环，框架只是语法糖；跳过这一步，遇到问题时很难排查。</p><h2 id="每篇文章的结构" tabindex="-1">每篇文章的结构 <a class="header-anchor" href="#每篇文章的结构" aria-label="Permalink to &quot;每篇文章的结构&quot;">​</a></h2><p>知识库里的文章结构基本一致：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>学习目标 → 概念讲解 → 可运行代码 → 常见坑 → 小测 → 延伸阅读</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><strong>学习目标</strong>：读之前先看，读完回来对照，检查自己是否真的掌握。</li><li><strong>常见坑</strong>：来自实际开发的经验，值得在写代码前看一遍。</li><li><strong>小测</strong>：先自己思考再展开答案。答不出来，说明需要回头重读对应小节。</li></ul><h2 id="三条学习路径" tabindex="-1">三条学习路径 <a class="header-anchor" href="#三条学习路径" aria-label="Permalink to &quot;三条学习路径&quot;">​</a></h2><p>不同背景的读者不必从头读到尾。<a href="/roadmap/">学习路线</a> 给出了三条路径：</p><table tabindex="0"><thead><tr><th>路径</th><th>适合谁</th><th>建议顺序</th><th>详情</th></tr></thead><tbody><tr><td>零基础入门</td><td>编程经验较少，或第一次接触大模型开发</td><td>00 → 01 → 02 → 03 → 04 → 05 → 06，配合项目 01–03</td><td><a href="/roadmap/beginner">零基础入门路径</a></td></tr><tr><td>工程师</td><td>有后端或全栈经验，想把 Agent 用到实际项目</td><td>00 速读 → 03 → 05 → 06 → 07 → 09 → 10 → 14 → 15</td><td><a href="/roadmap/engineer">工程师路径</a></td></tr><tr><td>架构师</td><td>负责技术选型、系统设计</td><td>00 → 07 → 11 → 12 → 14 → 15，结合论文与系统设计面试题</td><td><a href="/roadmap/architect">架构师路径</a></td></tr></tbody></table><p>如果你更喜欢按时间规划，可以参考 <a href="/roadmap/12-weeks">12 周学习计划</a>。</p><p>无论走哪条路径，都建议把 <a href="/projects/">实战项目</a> 穿插进来。读完 05 Tool Calling 就去做 <a href="/projects/02-tool-agent">天气日程工具 Agent</a>，读完 06 就去做 <a href="/projects/03-react-agent">手写 ReAct Agent</a>。<strong>只读不写，很难真正掌握 Agent 开发</strong>。</p><h2 id="代码语言切换" tabindex="-1">代码语言切换 <a class="header-anchor" href="#代码语言切换" aria-label="Permalink to &quot;代码语言切换&quot;">​</a></h2><p>示例代码以 <strong>Python</strong> 为主，同时提供 <strong>Go</strong> 和 <strong>Java</strong> 版本。有多语言代码的地方，代码块上方会有标签页：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────┬──────┬────────┐</span></span>
<span class="line"><span>│ Python  │  Go  │  Java  │   ← 点击切换</span></span>
<span class="line"><span>├─────────┴──────┴────────┤</span></span>
<span class="line"><span>│ ...代码...               │</span></span>
<span class="line"><span>└─────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>在任意代码块上切换语言后，<strong>全站所有代码块会同步切换</strong>，并记住你的选择。下次打开其他文章，看到的仍然是你选的语言。</p><p>几点说明：</p><ul><li><strong>Python 是 Agent 生态的主力语言</strong>，新框架、新 SDK 通常最先支持 Python。即使你主要写 Go 或 Java，也建议能读懂 Python 示例。</li><li>Go 示例尽量只用标准库，Java 示例基于 Java 17+ 标准 <code>HttpClient</code> 和 Jackson，便于理解底层原理。</li><li>少数内容天然只属于一种语言（例如某个只有 Python 版本的框架），文中会特别说明。</li></ul><h2 id="准备运行环境" tabindex="-1">准备运行环境 <a class="header-anchor" href="#准备运行环境" aria-label="Permalink to &quot;准备运行环境&quot;">​</a></h2><p>本站调用大模型统一使用 <strong>OpenAI 兼容的 Chat Completions API</strong>。这意味着你可以用 OpenAI，也可以用 DeepSeek、通义千问、Kimi 等提供兼容接口的服务，只需改配置，不用改代码。</p><p>所有示例通过三个环境变量读取配置：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .env 示例（不要提交到 Git）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENAI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-xxxx</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 你的 API Key</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENAI_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://api.openai.com/v1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 可选，换成其他厂商的兼容地址</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LLM_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gpt-4o-mini</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 模型名，仅为示例，以厂商文档为准</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>环境的具体搭建步骤见下一模块的 <a href="/guide/01-programming/dev-env">开发环境：Python / Go / Java</a>。</p><div class="warning custom-block"><p class="custom-block-title">保管好 API Key</p><p>不要把 Key 写进代码、截图或提交到仓库。把 <code>.env</code> 加入 <code>.gitignore</code>。一旦泄露，立即在厂商控制台作废并重新生成。</p></div><h2 id="高效学习的建议" tabindex="-1">高效学习的建议 <a class="header-anchor" href="#高效学习的建议" aria-label="Permalink to &quot;高效学习的建议&quot;">​</a></h2><ol><li><strong>读 → 跑 → 改 → 测</strong>。读完概念后把代码跑起来；然后改一处（换个工具、改个提示词），预测结果再验证。预测错了的地方，就是你理解不到位的地方。</li><li><strong>养成看「原始消息」的习惯</strong>。调试 Agent 时，把每一轮发给模型的完整 messages 和返回打印出来。绝大多数问题，看一眼上下文就知道原因。</li><li><strong>小步快跑，尽早做评估</strong>。哪怕只有 10 条测试用例，也比凭感觉判断「好像变好了」可靠。</li><li><strong>善用术语表</strong>。遇到不熟的术语查 <a href="/glossary">术语表</a>；需要更多资料看 <a href="/resources">学习资源</a>。</li><li><strong>用面试题自测</strong>。学完一个篇章，用 <a href="/interview/">面试题</a> 检验自己能否把概念讲清楚。</li></ol><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>跳过基础直接学框架</strong>。框架版本变化快，底层原理（消息结构、Tool Calling、循环）才是稳定的。</li><li><strong>只读不练</strong>。Agent 的很多细节（上下文膨胀、工具参数出错、无限循环）只有跑起来才能体会。</li><li><strong>一次学太多模块</strong>。每学完一个模块，最好做一个小练习或项目再继续。</li><li><strong>把 Key 硬编码在代码里</strong>。养成用环境变量的习惯，从第一个示例开始。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><p><strong>1. 你是一名有 5 年经验的 Java 后端工程师，想在公司项目里接入 Agent，应该选哪条路径？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>工程师路径。可以速读 00 导读，跳过大部分 01 编程基础，重点学习 03 API、05 Tool Calling、06 Agent 循环、07 上下文工程、09 RAG，并重视 14 评估和 15 生产化。代码语言切换到 Java，同时建议能读懂 Python 示例。另外可以重点看 <a href="/guide/11-frameworks/java-spring-ai">Java：Spring AI 与 LangChain4j</a>。</p></details><p><strong>2. 想把示例代码从 OpenAI 切换到其他兼容厂商，需要改什么？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>通常只需修改环境变量：<code>OPENAI_BASE_URL</code> 改成厂商的兼容接口地址，<code>OPENAI_API_KEY</code> 改成该厂商的 Key，<code>LLM_MODEL</code> 改成该厂商的模型名。代码本身不用改。不同厂商对某些参数的支持可能有差异，以厂商文档为准。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/roadmap/">学习路线总览</a></li><li><a href="/projects/">实战项目</a></li><li><a href="/guide/">知识库总览</a></li><li><a href="/about">关于本站</a></li></ul>`,40)])])}const b=s(i,[["render",l]]);export{g as __pageData,b as default};
